DO $$
DECLARE covered_km2 numeric;
BEGIN
    SELECT ST_Area(ST_Union(z.boundary)::geography) / 1e6 INTO covered_km2
    FROM zones z JOIN cities c ON c.id = z.city_id
    WHERE c.code = 'NS' AND z.level = 1;
    IF covered_km2 < 629 THEN
        RAISE EXCEPTION 'Pokrivenost nivoa 1 za Novi Sad je samo % km2, ocekivano ~699', round(covered_km2);
    END IF;
END $$;
